        const ai = a[i % n];
        const bi = b[i % n];
        const next = Array.from({ length: half + 1 }, () => Infinity);
        for (let j = 0; j <= half; j++) {
            if (dp[j] === Infinity) continue;
            if (j < half) next[j + 1] = Math.min(next[j + 1], dp[j] + ai);
            if (j > 0) next[j - 1] = Math.min(next[j - 1], dp[j] + bi);
        }
        dp.length = 0;
        for (let j = 0; j <= half; j++) dp[j] = next[j];
    }
    console.log(dp[0]);
});
