    input: process.stdin,
    output: process.stdout
});

let input = [];
rl.on('line', (line) => {
    input.push(line);
}).on('close', () => {
    const [n, m] = input[0].split(' ').map(Number);
    const a = input[1].split(' ').map(Number);
    const b = input[2].split(' ').map(Number);
    const total = n * m;
    const half = total / 2;

    // Initialize DP table
    let dp = Array.from({ length: half + 1 }, () => new Array(n + 1).fill(Infinity));
    dp[0][0] = 0;

    for (let i = 0; i < total; i++) {
        let new_dp = Array.from({ length: half + 1 }, () => new Array(n + 1).fill(Infinity));
        const ai = a[i % n];
        const bi = b[i % n];
        for (let j = 0; j <= half; j++) {
            for (let k = 0; k <= n; k++) {
                if (dp[j][k] === Infinity) continue;
                // Place '('
                if (j + 1 <= half) {
                    const new_k = Math.min(k + 1, n);
                    if (new_dp[j + 1][new_k] > dp[j][k] + ai) {
                        new_dp[j + 1][new_k] = dp[j][k] + ai;
                    }
                }
                // Place ')'
                if (k > 0) {
                    const new_k = k - 1;
                    if (new_dp[j][new_k] > dp[j][k] + bi) {
                        new_dp[j][new_k] = dp[j][k] + bi;
                    }
                }
            }
        }
        dp = new_dp;
    }

    console.log(dp[half][0]);
});
